STORY = [('paquita', 'Hola, buenas, ¿qué tal? Mira, me pones unos torreznos y una ginebra.', 'Hello there, how are you? Look, could you get me some crispy pork belly and a gin?', [(356, 'Hola, buenas, ¿qué tal?'), (357, 'Mira, me pones unos torreznos'), (360, 'ginebra')], ''), ('silvia', 'Pues mira, torreznos no tenemos, pero te puedo poner unos quicos si quieres.', "Well look, we don't have pork belly, though I can give you some crunchy corn nuts if you want.", [(358, 'Pues mira, torreznos no tenemos'), (359, 'pero te puedo poner unos quicos si quieres')], ''), ('silvia', '¿Y de qué ginebra lo quieres?', 'And what kind of gin would you like?', [(360, 'de qué ginebra lo quieres')], ''), ('paquita', 'Yo bebo la de siempre, gracias.', 'I drink my usual one, thank you.', [(365, 'bebo'), (367, 'Gracias')], ''), ('silvia', 'Pues perfecto. Mira qué fácil.', 'Perfect then. Look how easy.', [(366, 'Pues perfecto'), (367, 'Mira qué fácil')], ''), ('paquita', 'Perdona, ¿tú eres la prima de Álex?', "Excuse me, are you Álex's cousin?", [(368, 'Perdona, ¿tú eres'), (380, 'primo Álex')], ''), ('sofi', 'Sí, ¿cómo lo sabes?', 'Yes, how do you know?', [(369, 'Sí, ¿cómo lo sabes?')], ''), ('paquita', 'Una que sabe cosas. Quieres ser actriz, ¿verdad? ¿Y qué tal te va?', "Just someone who knows things. You want to be an actress, right? And how's it going?", [(369, 'Una que sabe cosas'), (370, 'Quieres ser actriz, ¿verdad?'), (371, '¿Y qué tal te va?')], ''), ('sofi', 'Bueno, a ver, me acaban de coger para hacer un corto.', "Well, let's see, they've just picked me to do a short film.", [(372, 'Bueno, a ver, me acaban de coger para hacer un corto')], ''), ('silvia', 'Porque es buenísima. La niña es buenísima. Pero ¿y usted quién es?', "Because she's brilliant. The girl is brilliant. Though who are you?", [(373, 'Porque es buenísima. La niña es buenísima'), (374, 'Pero ¿y usted quién es?')], ''), ('paquita', '¿Yo quién soy? Yo soy Paquita Salas y soy representante.', "Who am I? I am Paquita Salas, and I'm a talent agent.", [(374, '¿Yo quién soy?'), (375, 'Yo soy Paquita Salas y soy representante')], ''), ('paquita', 'Llevo la empresa PS Management y somos expertos en descubrir nuevos talentos.', 'I run PS Management, and we are experts at discovering new talent.', [(376, 'Llevo la empresa PS Management'), (377, 'y somos expertos en descubrir nuevos talentos')], ''), ('paquita', 'He visto tu material y me ha encantado. Tu primo Álex es muy amigo mío.', "I've seen your showreel and loved it. Your cousin Álex is a close friend of mine.", [(378, 'He visto tu material y me ha encantado'), (380, 'Tu primo Álex'), (380, 'es muy amigo mío')], '')]
